"use strict";
window.LogDetails={items:[],missions:[],token:0,events:[],archive:[],context:null,
 // 6.0.5: Auftragsvorlagen (18 MB, gepackt 1,4 MB) erst laden, wenn ein Auftrag aus einem Bauplan-Popup geöffnet wird
 async templates(){if(this.missions)return this.missions;if(!this._templates)this._templates=SCUI.api('/api/missions/templates').then(r=>this.missions=r.missions||[]).finally(()=>{this._templates=null;});return this._templates;},
 async init(items){this.items=items;this.missions=null;if(document.getElementById('logDetail'))return;
 document.body.insertAdjacentHTML('beforeend','<dialog id="logDetail" class="log-detail"><button type="button" class="quiet-button" id="logDetailClose">Schließen ×</button><div id="logDetailBody"></div></dialog>');document.getElementById('logDetailClose').onclick=()=>document.getElementById('logDetail').close();},
 mission(m,context=null){this.context=context;const e=SCUI.escape,instance=m.logInstance;return `${context?.item?'<button type="button" class="quiet-button" data-log-back>← Zurück zum Bauplan</button>':''}<h2>${MissionText.render(m,'title')}</h2><p>${e(m.contractor||'Unbekannter Auftraggeber')} · ${e((m.systems||[]).join(' · '))}</p>${MissionText.rewards(m)}${instance?`<dl><dt>Ziel</dt><dd>${e(instance.target||'Unbekannt')}</dd><dt>Einsatzort</dt><dd>${e(instance.location||'Unbekannt')}</dd></dl>`:''}<p class="log-description">${MissionText.render(m)}</p>${MissionText.cargo(m)}<p>Voraussetzungen: ${e((m.prerequisites||[]).join(' · ')||'Keine weiteren Angaben')}</p><button type="button" class="quiet-button" data-log-obs="${e(m.id||m.debugName)}" data-log-guid="${e(instance?.guid||'')}">${context?.event?'Erhaltenen Bauplan in OBS anzeigen':(instance?.status==='Complete'?'Absolvierten Auftrag in OBS anzeigen':'Auftrag in OBS anzeigen')}</button>`;},
 show(html){this.token++;const d=document.getElementById('logDetail');document.getElementById('logDetailBody').innerHTML=html;if(!d.open)d.showModal();
 d.querySelector('[data-log-back]')?.addEventListener('click',()=>{const c=this.context;void this.item(c.item,c.event);});
 d.querySelectorAll('[data-log-obs]').forEach(b=>b.onclick=async()=>{try{const c=this.context;await SCUI.api('/api/obs',c?.event?{kind:'found-item',event:c.event}:b.dataset.logGuid?{kind:'archive-mission',guid:b.dataset.logGuid}:{kind:'mission-brief',mission:b.dataset.logObs});b.textContent='An OBS gesendet';}catch(err){b.textContent=err.message;}});},
 async item(id,eventId=null){const i=this.items.find(i=>String(i.id)===String(id)||i.ini===id);if(!i)return;const e=SCUI.escape;this.context={item:i.id,event:eventId};
 this.show(`<h2>${e(i.name)}</h2><p>${e(i.category)} · ${e(i.subcategory)}</p><p class="log-description">${e(i.description||'').replaceAll('\\n','<br>')}</p><div id="logDetailMedia">Bilder werden geladen …</div><h3>Auftragsquellen</h3><div id="logSources"></div>${eventId?'<button class="quiet-button" data-found-obs>Erhaltenen Bauplan in OBS anzeigen</button>':''}`);
 document.querySelector('[data-found-obs]')?.addEventListener('click',async event=>{const button=event.currentTarget;try{await SCUI.api('/api/obs',{kind:'found-item',event:eventId});button.textContent='An OBS gesendet';}catch(err){button.textContent=err.message;}});
 const token=this.token;try{const result=await SCUI.api('/api/log-details/'+encodeURIComponent(i.id));if(token!==this.token)return;const data=result.data||{};document.getElementById('logDetailMedia').innerHTML=(data.images||[]).filter(img=>img.thumbnail_url?.startsWith('/media/')).map(img=>`<img src="${e(img.thumbnail_url)}" alt="${e(i.name)}"/>`).join('');
 const sources=result.missions||[];document.getElementById('logSources').innerHTML=sources.map(m=>`<button class="quiet-button" data-loaded-mission="${e(m.id||m.debugName)}">${e(m.title||m.debugName)}</button>`).join('')||'<p>Keine Auftragsquelle hinterlegt.</p>';
 document.querySelectorAll('[data-loaded-mission]').forEach(b=>b.onclick=async()=>{let m=(await this.templates()).find(m=>(m.id||m.debugName)===b.dataset.loadedMission)||sources.find(m=>(m.id||m.debugName)===b.dataset.loadedMission);const event=this.events.find(e=>e.id===eventId),row=this.archive.find(row=>row.guid===event?.mission?.guid);if(event?.mission?.guid){const actual=row?.mission||(await SCUI.api('/api/missions/instance/'+encodeURIComponent(event.mission.guid))).mission;if(actual?.id===m.id)m=actual;}if(token!==this.token)return;this.show(this.mission(m,{item:i.id,event:eventId}));});}catch(err){if(token===this.token)document.getElementById('logDetailMedia').textContent=err.message;}
 }};
